class Solution {
    public boolean isMatch(String s, String p) {
        int m = s.length();
        int n = p.length();
        boolean[][] dp = new boolean[m + 1][n + 1];
        dp[0][0] = true;
        for (int j = 2; j <= n; j++) {
            if (p.charAt(j - 1) == '*') {
                dp[0][j] = dp[0][j - 2];
            }
        }
        for (int i = 1; i <= m; i++) {
            for (int j = 1; j <= n; j++) {
                char pattern = p.charAt(j - 1);
                if (pattern == '*') {
                    dp[i][j] = dp[i][j - 2];
                    char previous = p.charAt(j - 2);
                    if (matches(s.charAt(i - 1), previous)) {
                        dp[i][j] = dp[i][j] || dp[i - 1][j];
                    }
                } else if (matches(s.charAt(i - 1), pattern)) {
                    dp[i][j] = dp[i - 1][j - 1];
                }
            }
        }
        return dp[m][n];
    }

    private boolean matches(char value, char pattern) {
        return pattern == '.' || value == pattern;
    }
}

class Solution {
    private Boolean[][] memo;

    public boolean isMatch(String s, String p) {
        memo = new Boolean[s.length() + 1][p.length() + 1];
        return solve(s, p, 0, 0);
    }

    private boolean solve(String s, String p, int i, int j) {
        if (memo[i][j] != null) {
            return memo[i][j];
        }
        if (j == p.length()) {
            memo[i][j] = i == s.length();
            return memo[i][j];
        }
        boolean firstMatch = i < s.length()
                && (p.charAt(j) == '.' || p.charAt(j) == s.charAt(i));
        boolean answer;
        if (j + 1 < p.length() && p.charAt(j + 1) == '*') {
            answer = solve(s, p, i, j + 2)
                    || (firstMatch && solve(s, p, i + 1, j));
        } else {
            answer = firstMatch && solve(s, p, i + 1, j + 1);
        }
        memo[i][j] = answer;
        return answer;
    }
}

class Solution {
    public boolean isMatch(String s, String p) {
        int m = s.length();
        int n = p.length();
        boolean[][] suffix = new boolean[m + 1][n + 1];
        suffix[m][n] = true;
        for (int i = m; i >= 0; i--) {
            for (int j = n - 1; j >= 0; j--) {
                boolean firstMatch = i < m
                        && (p.charAt(j) == '.' || p.charAt(j) == s.charAt(i));
                if (j + 1 < n && p.charAt(j + 1) == '*') {
                    suffix[i][j] = suffix[i][j + 2]
                            || (firstMatch && suffix[i + 1][j]);
                } else {
                    suffix[i][j] = firstMatch && suffix[i + 1][j + 1];
                }
            }
        }
        return suffix[0][0];
    }
}

class Solution {
    public boolean isMatch(String s, String p) {
        java.util.List<Token> tokens = tokenize(p);
        int m = s.length();
        int t = tokens.size();
        boolean[][] dp = new boolean[t + 1][m + 1];
        dp[0][0] = true;
        for (int tokenIndex = 1; tokenIndex <= t; tokenIndex++) {
            Token token = tokens.get(tokenIndex - 1);
            if (token.star) {
                for (int length = 0; length <= m; length++) {
                    dp[tokenIndex][length] = dp[tokenIndex - 1][length];
                }
                for (int length = 1; length <= m; length++) {
                    if (matches(s.charAt(length - 1), token.ch) && dp[tokenIndex][length - 1]) {
                        dp[tokenIndex][length] = true;
                    }
                }
            } else {
                for (int length = 1; length <= m; length++) {
                    dp[tokenIndex][length] = dp[tokenIndex - 1][length - 1]
                            && matches(s.charAt(length - 1), token.ch);
                }
            }
        }
        return dp[t][m];
    }

    private java.util.List<Token> tokenize(String p) {
        java.util.ArrayList<Token> tokens = new java.util.ArrayList<>();
        for (int i = 0; i < p.length(); i++) {
            boolean star = i + 1 < p.length() && p.charAt(i + 1) == '*';
            tokens.add(new Token(p.charAt(i), star));
            if (star) {
                i++;
            }
        }
        return tokens;
    }

    private boolean matches(char value, char pattern) {
        return pattern == '.' || value == pattern;
    }

    private static class Token {
        final char ch;
        final boolean star;

        Token(char ch, boolean star) {
            this.ch = ch;
            this.star = star;
        }
    }
}

class Solution {
    public boolean isMatch(String s, String p) {
        java.util.Set<Integer> current = closure(java.util.Set.of(0), p);
        for (int index = 0; index < s.length(); index++) {
            char value = s.charAt(index);
            java.util.Set<Integer> next = new java.util.HashSet<>();
            for (int state : current) {
                if (state >= p.length()) {
                    continue;
                }
                char pattern = p.charAt(state);
                boolean starred = state + 1 < p.length() && p.charAt(state + 1) == '*';
                if (matches(value, pattern)) {
                    if (starred) {
                        next.add(state);
                    } else {
                        next.add(state + 1);
                    }
                }
            }
            current = closure(next, p);
        }
        return current.contains(p.length());
    }

    private java.util.Set<Integer> closure(java.util.Set<Integer> seeds, String p) {
        java.util.HashSet<Integer> reached = new java.util.HashSet<>();
        java.util.ArrayDeque<Integer> queue = new java.util.ArrayDeque<>(seeds);
        while (!queue.isEmpty()) {
            int state = queue.removeFirst();
            if (!reached.add(state)) {
                continue;
            }
            if (state + 1 < p.length() && p.charAt(state + 1) == '*') {
                queue.addLast(state + 2);
            }
        }
        return reached;
    }

    private boolean matches(char value, char pattern) {
        return pattern == '.' || value == pattern;
    }
}
